import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, uniform, vec3, vec4, mix, smoothstep, distance, float, positionLocal, min as tslMin } from 'three/tsl';
import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'badge-pricing';

  const colors = {
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    surface: 0x0b0b10,
  };

  const width = 0.9;
  const height = 0.32;
  const radius = height / 2;

  const geometry = new THREE.PlaneGeometry(width, height, 32, 8);

  const map = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  map.wrapS = THREE.RepeatWrapping;
  map.wrapT = THREE.RepeatWrapping;

  const material = new MeshStandardNodeMaterial();
  material.roughness = 0.55;
  material.metalness = 0.45;
  material.clearcoat = 0.2;
  material.transparent = true;

  const focusUniform = uniform(float(0.0));
  const hoverUniform = uniform(float(0.0));

  const uvNode = uv();
  const grain = texture(map, uvNode.mul(3.0));

  // capsule mask: distance from edges accounting for rounded ends
  const centered = uvNode.sub(0.5);
  const halfW = float(0.5 - radius / width);
  const clampedX = tslMin(centered.x.abs(), halfW);
  const capsuleDist = distance(vec3(clampedX, centered.y, 0.0), vec3(0.0, 0.0, 0.0));
  const edgeFade = smoothstep(float(0.5 - 0.02), float(0.5), capsuleDist.mul(1.0));

  const baseColor = mix(vec3(colors.surface / 0xffffff, 0, 0), vec3(0.043, 0.043, 0.062), 0.5);
  const inkColor = vec3(0.086, 0.086, 0.114);
  const paperColor = vec3(0.910, 0.925, 0.949);
  const accentColor = vec3(1.0, 0.165, 0.219);

  const grainInfluence = grain.r.mul(0.15);
  const bodyColor = mix(inkColor, paperColor.mul(0.15).add(inkColor.mul(0.85)), grainInfluence);

  // edge light ring near capsule border, intensified by hover/focus
  const edgeRing = smoothstep(float(0.42), float(0.5), capsuleDist).sub(edgeFade).clamp(0.0, 1.0);
  const focusBoost = focusUniform.mul(0.6).add(hoverUniform.mul(0.4));
  const edgeGlow = edgeRing.mul(accentColor).mul(float(1.0).add(focusBoost.mul(2.0)));

  const finalColor = bodyColor.add(edgeGlow);
  const alpha = float(1.0).sub(edgeFade).clamp(0.0, 1.0);

  material.colorNode = vec4(finalColor, alpha);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'badge-pricing-mesh';
  group.add(mesh);

  group.position.set(1.25, 0.7000000000000001, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // gsap timelines registry for cleanup
  const timelines = [];

  const baseY = group.position.y;
  const basePos = group.position.clone();

  function riseIn() {
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.3,
      ease: 'power3.out',
    });
    hoverUniform.value = 1.0;
    timelines.push(tl);
    return tl;
  }

  function riseOut() {
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: baseY,
      duration: 0.3,
      ease: 'power3.out',
    });
    hoverUniform.value = 0.0;
    timelines.push(tl);
    return tl;
  }

  function pressDown() {
    const tl = gsap.timeline();
    tl.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    }).to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'back.out',
    });
    timelines.push(tl);
    return tl;
  }

  group.userData.handlers = {
    onPointerOver: () => {
      riseIn();
    },
    onPointerOut: () => {
      riseOut();
    },
    onPointerDown: () => {
      pressDown();
    },
    onClick: () => {
      pressDown();
      focusUniform.value = 1.0;
      if (group.userData.emit) {
        group.userData.emit('hub-pricing.select', { source: 'badge-pricing' });
      }
    },
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    group.position.copy(basePos);
  };

  return group;
}
